-- Lo que falta por averiguar del Marbella (síntesis de taller) como tareas de su restauración en curso,
-- en una fase «Datos técnicos pendientes». Si no hay restauración abierta, no hace nada. Se puede aplicar varias veces.
INSERT INTO `fases` (`restauracion_id`, `nombre`, `orden`)
SELECT r.`id`, 'Datos técnicos pendientes', (SELECT COALESCE(MAX(`orden`), 0) + 1 FROM `fases` WHERE `restauracion_id` = r.`id`)
FROM `restauraciones` r WHERE r.`id` = (SELECT r.`id` FROM `restauraciones` r WHERE r.`vehiculo_id` = (SELECT CASE WHEN COUNT(*) = 1 THEN MAX(`id`) END FROM `vehiculos` WHERE lower(`alias`) LIKE '%marbella%' OR lower(coalesce(`modelo`, '')) LIKE '%marbella%' OR replace(replace(upper(`matricula`), '-', ''), ' ', '') IN ('A9742DB', 'A9748DB')) AND r.`estado` != 'terminada' ORDER BY r.`fecha_inicio` DESC, r.`id` DESC LIMIT 1)
AND NOT EXISTS (SELECT 1 FROM `fases` x WHERE x.`restauracion_id` = r.`id` AND x.`nombre` = 'Datos técnicos pendientes');
--> statement-breakpoint
